package com.eventdrivencommerce.inventory.infrastructure.outbox;
import com.fasterxml.jackson.databind.JsonNode;import jakarta.persistence.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="outbox_events") class OutboxJpaEntity {
 @Id @Column(name="event_id")UUID eventId;@Column(name="aggregate_id",nullable=false)UUID aggregateId;@Column(name="event_type",nullable=false)String eventType;@Column(name="event_version",nullable=false)int eventVersion;@Column(name="correlation_id",nullable=false)UUID correlationId;@Column(name="causation_id",nullable=false)UUID causationId;@Column(name="occurred_at",nullable=false)Instant occurredAt;@JdbcTypeCode(SqlTypes.JSON)@Column(nullable=false,columnDefinition="jsonb")JsonNode payload;@Enumerated(EnumType.STRING)@Column(nullable=false)OutboxStatus status;@Column(nullable=false)int attempts;@Column(name="next_attempt_at",nullable=false)Instant nextAttemptAt;@Column(name="published_at")Instant publishedAt;@Column(name="last_error")String lastError;@Column(name="created_at",nullable=false)Instant createdAt;
 protected OutboxJpaEntity(){}static OutboxJpaEntity pending(UUID id,UUID aggregate,String type,UUID correlation,UUID causation,Instant now,JsonNode body){var e=new OutboxJpaEntity();e.eventId=id;e.aggregateId=aggregate;e.eventType=type;e.eventVersion=1;e.correlationId=correlation;e.causationId=causation;e.occurredAt=now;e.payload=body;e.status=OutboxStatus.PENDING;e.nextAttemptAt=now;e.createdAt=now;return e;}void published(Instant now){status=OutboxStatus.PUBLISHED;publishedAt=now;lastError=null;}void failed(Instant now,String error){attempts++;nextAttemptAt=now.plusSeconds(Math.min(60,1L<<Math.min(attempts,6)));lastError=error==null?"Unknown failure":error.substring(0,Math.min(500,error.length()));}
}
